import{d as g,C as i,o as h,c as u,a3 as e,E as a,j as t,a as m}from"./chunks/framework.Q4yG9rk_.js";const b=JSON.parse('{"title":"论语·季氏","description":"《论语》第 16 篇「季氏」——十四章原文与导读。季氏将伐颛臾、不患寡而患不均、益者三友三乐、君子三戒三畏、君子有九思。","frontmatter":{"title":"论语·季氏","description":"《论语》第 16 篇「季氏」——十四章原文与导读。季氏将伐颛臾、不患寡而患不均、益者三友三乐、君子三戒三畏、君子有九思。","category":"guide","aliases":["季氏","季氏篇","季氏第十六","论语季氏","lunyu 季氏"],"source":["《论语》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/lunyu/chapter-16.md","filePath":"lizhimingde/sishu-wujing/lunyu/chapter-16.md","lastUpdated":1790316338000}'),p={name:"lizhimingde/sishu-wujing/lunyu/chapter-16.md"},x=g({...p,setup(y){const s=[{id:"yi",label:"一、季氏将伐颛臾",showLabel:!0,sentences:[["季氏将伐",{text:"颛臾",glossary:"zhuanyu"},"。冉有、季路见于孔子曰：“季氏将有事于颛臾。”孔子曰：“求！无乃尔是过与？夫颛臾，昔者先王以为东蒙主，且在邦域之中矣，是社稷之臣也。何以伐为？”冉有曰：“夫子欲之，吾二臣者皆不欲也。”孔子曰：“求！周任有言曰：‘",{text:"陈力就列",glossary:"chenlijiuolie"},"，不能者止。’危而不持，颠而不扶，则将焉用彼",{text:"相",glossary:"xiang-help"},"矣？且尔言过矣，",{text:"虎兕出于柙，龟玉毁于椟中",glossary:"husichuyuzhaxiazhi"},"，是谁之过与？”冉有曰：“今夫颛臾，固而近于费。今不取，后世必为子孙忧。”孔子曰：“求！君子疾夫",{text:"舍曰欲之而必为之辞",glossary:"sheriyuzhi"},"。丘也闻有国有家者，不患寡而患不均，不患贫而患不安。盖均无贫，和无寡，安无倾。夫如是，故远人不服，则修文德以来之。既来之，则安之。今由与求也，相夫子，远人不服而不能来也，邦分崩离析而不能守也；而谋动干戈于邦内。吾恐季孙之忧，不在颛臾，而在萧墙之内也。”"]],note:"季氏将伐颛臾。冉有、季路见于孔子曰：「季氏将有事于颛臾」——季氏将对颛臾用兵。孔子曰：「求！无乃尔是过与」——冉求！这怕要算是你的过失吧？「夫颛臾，昔者先王以为东蒙主，且在邦域之中矣，是社稷之臣也。何以伐为」——颛臾，昔者先王使之主东蒙之祀，且在邦域之内，是国家之臣；何以伐之？冉有曰：「夫子欲之，吾二臣者皆不欲也」——季孙欲如此，我二人皆不欲。孔子曰：「求！周任有言曰：陈力就列，不能者止」——能尽力便居其位，不能便止。又以「危而不持，颠而不扶，则将焉用彼相矣」「虎兕出于柙，龟玉毁于椟中，是谁之过与」责之。冉有曰：今颛臾城固而近于费，今不取，后世必为子孙忧。孔子曰：「求！君子疾夫舍曰欲之而必为之辞」——君子恶那种不肯直说想要、却必另找说辞者。继提「均无贫，和无寡，安无倾」与「远人不服，则修文德以来之」；末以「吾恐季孙之忧，不在颛臾，而在萧墙之内也」作结。此为全书论政最长的一段。"},{id:"er",label:"二、天下有道，则礼乐征伐自天子出",showLabel:!0,sentences:[["孔子曰：“天下有道，则礼乐征伐自天子出；天下无道，则礼乐征伐自诸侯出。自诸侯出，盖十世希不失矣；自大夫出，五世希不失矣；",{text:"陪臣执国命",glossary:"peichenzhiguoming"},"，三世希不失矣。天下有道，则政不在大夫。天下有道，则庶人不议。”"]],note:"「天下有道，则礼乐征伐自天子出；天下无道，则礼乐征伐自诸侯出」——天下有道，则制礼作乐、出兵征伐皆由天子出；无道则由诸侯出。「自诸侯出，盖十世希不失矣；自大夫出，五世希不失矣；陪臣执国命，三世希不失矣」——由诸侯出，大概十世而少有不失者；由大夫出，五世而少有不失者；家臣执国命，三世而少有不失者。「天下有道，则政不在大夫。天下有道，则庶人不议」——天下有道，政权不在大夫；天下有道，庶人也不非议。"},{id:"san",label:"三、禄之去公室五世矣",showLabel:!0,sentences:[["孔子曰：“禄之去公室五世矣，政逮于大夫四世矣，故夫",{text:"三桓",glossary:"sanhuan"},"之子孙微矣。”"]],note:"「禄之去公室五世矣，政逮于大夫四世矣，故夫三桓之子孙微矣」——爵禄之权离公室已五世，政权落于大夫已四世，故三桓（鲁三家）之子孙也衰微了。"},{id:"si",label:"四、益者三友，损者三友",showLabel:!0,sentences:[["孔子曰：“益者三友，损者三友。友直，友",{text:"谅",glossary:"liang-xin2"},"，友多闻，益矣。友",{text:"便辟",glossary:"bianpi"},"，友",{text:"善柔",glossary:"shanrou"},"，友",{text:"便佞",glossary:"bianning"},"，损矣。”"]],note:"「益者三友，损者三友」——益友三种，损友三种。「友直，友谅，友多闻，益矣」——友正直、友信实、友多闻，有益。「友便辟，友善柔，友便佞，损矣」——友谄媚逢迎、友面顺背毁、友巧言善辩，有损。"},{id:"wu",label:"五、益者三乐，损者三乐",showLabel:!0,sentences:[["孔子曰：“益者三乐，损者三乐。乐节礼乐，乐道人之善，乐多贤友，益矣。乐骄乐，乐",{text:"佚游",glossary:"yiyou"},"，乐",{text:"晏乐",glossary:"yanle"},"，损矣。”"]],note:"「益者三乐，损者三乐」——有益之乐三种，有损之乐三种。「乐节礼乐，乐道人之善，乐多贤友，益矣」——以礼乐自节为乐、以称道人之善为乐、以多贤友为乐，有益。「乐骄乐，乐佚游，乐晏乐，损矣」——以骄纵为乐、以游荡为乐、以宴饮为乐，有损。"},{id:"liu",label:"六、侍于君子有三愆",showLabel:!0,sentences:[["孔子曰：“侍于君子有三",{text:"愆",glossary:"qian-guo"},"：言未及之而言谓之",{text:"躁",glossary:"zao"},"，言及之而不言谓之",{text:"隐",glossary:"yin-cang"},"，未见颜色而言谓之",{text:"瞽",glossary:"gu-mang2"},"。”"]],note:"「侍于君子有三愆」——侍奉君子有三种过失：「言未及之而言谓之躁」（未及言而言，谓之躁）；「言及之而不言谓之隐」（当言而不言，谓之隐）；「未见颜色而言谓之瞽」（未见颜色而言，谓之瞽）。"},{id:"qi",label:"七、君子有三戒",showLabel:!0,sentences:[["孔子曰：“君子有三戒：少之时，血气未定，戒之在色；及其壮也，血气方刚，戒之在斗；及其老也，血气既衰，戒之在得。”"]],note:"「君子有三戒」——君子有三戒：「少之时，血气未定，戒之在色」；「及其壮也，血气方刚，戒之在斗」；「及其老也，血气既衰，戒之在得」。"},{id:"ba",label:"八、君子有三畏",showLabel:!0,sentences:[["孔子曰：“君子有三畏：畏天命，畏大人，畏圣人之言。小人不知天命而不畏也，",{text:"狎",glossary:"xia-xia"},"大人，侮圣人之言。”"]],note:"「君子有三畏：畏天命，畏大人，畏圣人之言」——畏天命、畏大人（在位者）、畏圣人之言。「小人不知天命而不畏也，狎大人，侮圣人之言」——小人不知天命故不畏，戏狎大人，轻侮圣人之言。"},{id:"jiu",label:"九、生而知之者，上也",showLabel:!0,sentences:[["孔子曰：“生而知之者，上也；学而知之者，次也；困而学之，又其次也；困而不学，民斯为下矣。”"]],note:"「生而知之者，上也；学而知之者，次也；困而学之，又其次也；困而不学，民斯为下矣」——生而知之者，上等；学而知之者，次之；困而学之者，又次之；困而不学者，其为下等矣。四层。"},{id:"shi",label:"十、君子有九思",showLabel:!0,sentences:[["孔子曰：“君子有九思：视思明，听思聪，色思温，貌思恭，言思忠，事思敬，疑思问，忿思难，见得思义。”"]],note:"「君子有九思」——君子有九思：「视思明」（视而思其明），「听思聪」，「色思温」，「貌思恭」，「言思忠」，「事思敬」，「疑思问」，「忿思难」，「见得思义」。"},{id:"shiyi",label:"十一、见善如不及",showLabel:!0,sentences:[["子曰：“见善如不及，见不善如探汤。吾见其人矣，吾闻其语矣。隐居以求其志，行义以达其道。吾闻其语矣，未见其人也。”"]],note:"「见善如不及，见不善如探汤」——见善如赶之不及，见不善如手探沸汤。「吾见其人矣，吾闻其语矣」——我见过这样的人，也听过这样的话。「隐居以求其志，行义以达其道。吾闻其语矣，未见其人也」——隐居以全其志，行义以达其道；我听过这样的话，却未见这样的人。"},{id:"shier",label:"十二、齐景公有马千驷",showLabel:!0,sentences:[["齐景公有马",{text:"千驷",glossary:"qiansi"},"，死之日，民无德而称焉。伯夷叔齐饿于首阳之下，民到于今称之。其斯之谓与？"]],note:"「齐景公有马千驷，死之日，民无德而称焉」——齐景公有马四千匹，死之日，百姓无可称其德。「伯夷叔齐饿于首阳之下，民到于今称之」——伯夷、叔齐饿死于首阳山下，百姓至今称道之。「其斯之谓与」——大概说的就是这个意思吧！"},{id:"shisan",label:"十三、陈亢问于伯鱼",showLabel:!0,sentences:[["陈亢问于伯鱼曰：“子亦有异闻乎？”对曰：“未也。尝独立，鲤趋而过庭。曰：‘学诗乎？’对曰：‘未也。’‘不学诗，无以言。’鲤退而学诗。他日又独立，鲤趋而过庭。曰：‘学礼乎？’对曰：‘未也。’‘不学礼，无以立。’鲤退而学礼。闻斯二者。”陈亢退而喜曰：“问一得三：闻诗，闻礼，又闻君子之远其子也。”"]],note:"陈亢问于伯鱼（孔鲤）曰：「子亦有异闻乎」——你在老师那里也有不同的教诲吗？对曰：「未也。尝独立，鲤趋而过庭。曰：『学诗乎？』对曰：『未也。』『不学诗，无以言。』鲤退而学诗。他日又独立，鲤趋而过庭。曰：『学礼乎？』对曰：『未也。』『不学礼，无以立。』鲤退而学礼」。「陈亢退而喜曰：问一得三：闻诗，闻礼，又闻君子之远其子也」——陈亢退而喜曰：问一而得三：闻《诗》、闻礼，又闻君子之不偏爱其子。"},{id:"shisi",label:"十四、邦君之妻",showLabel:!0,sentences:[["邦君之妻，君称之曰“夫人”，夫人自称曰“小童”；邦人称之曰“君夫人”，称诸异邦曰“寡小君”；异邦人称之亦曰“君夫人”。"]],note:"「邦君之妻，君称之曰『夫人』，夫人自称曰『小童』；邦人称之曰『君夫人』，称诸异邦曰『寡小君』；异邦人称之亦曰『君夫人』」——国君之妻：君称之为「夫人」，其自称「小童」；本国人称之「君夫人」，对他国称「寡小君」；他国人亦称「君夫人」。此章记称谓正名之例。"}],r=[{id:"zhuanyu",term:"颛臾",pinyin:"zhuān yú",meaning:"鲁国的附属小国（风姓，相传为伏羲之后），当时为季氏采邑费地附近。"},{id:"chenlijiuolie",term:"陈力就列",pinyin:"chén lì jiù liè",meaning:"施展才力去就任职位。周任：古之良史。不能者止：不能胜任就该辞职。"},{id:"xiang-help",term:"相",pinyin:"xiàng",meaning:"辅佐、扶助（此指扶助盲者的人，引申为辅佐之臣）。"},{id:"husichuyuzhaxiazhi",term:"虎兕出于柙，龟玉毁于椟中",pinyin:"hǔ sì chū yú xiá， guī yù huǐ yú dú zhōng",meaning:"猛兽从笼中跑出，龟甲宝玉在匣里毁坏。兕：犀牛；柙：兽笼；椟：木匣。喻管事的人失职。"},{id:"sheriyuzhi",term:"舍曰欲之而必为之辞",pinyin:"shě yuē yù zhī ér bì wèi zhī cí",meaning:"不肯直说自己想要，却一定要另找一套说辞。此为孔子批评冉有的话。"},{id:"peichenzhiguoming",term:"陪臣执国命",pinyin:"péi chén zhí guó mìng",meaning:"大夫的家臣把持国家政权。陪臣：大夫的家臣。"},{id:"sanhuan",term:"三桓",pinyin:"sān huán",meaning:"鲁国孟孙、叔孙、季孙三家（皆桓公之后），世代把持鲁政。"},{id:"liang-xin2",term:"谅",pinyin:"liàng",meaning:"诚信、信实（此处的「友谅」是褒义，与「君子贞而不谅」的「谅」义别）。"},{id:"bianpi",term:"便辟",pinyin:"pián pì",meaning:"逢迎谄媚。便：习熟；辟：同「僻」，偏邪。"},{id:"shanrou",term:"善柔",pinyin:"shàn róu",meaning:"工于柔媚、当面顺从。"},{id:"bianning",term:"便佞",pinyin:"pián nìng",meaning:"巧言善辩而心术不正。"},{id:"yiyou",term:"佚游",pinyin:"yì yóu",meaning:"放纵游荡。佚：同「逸」，放荡。"},{id:"yanle",term:"晏乐",pinyin:"yàn lè",meaning:"沉溺于宴饮之乐。"},{id:"qian-guo",term:"愆",pinyin:"qiān",meaning:"过失、差错。"},{id:"zao",term:"躁",pinyin:"zào",meaning:"急躁（该说的时候还没到就抢先说）。"},{id:"yin-cang",term:"隐",pinyin:"yǐn",meaning:"隐匿、藏私（该说却不说）。"},{id:"gu-mang2",term:"瞽",pinyin:"gǔ",meaning:"盲人（此处指像瞎子一样不看人脸色）。"},{id:"xia-xia",term:"狎",pinyin:"xiá",meaning:"轻慢、不尊重。"},{id:"qiansi",term:"千驷",pinyin:"qiān sì",meaning:"四千匹马。驷：同驾一车的四匹马。"}];return(d,n)=>{const o=i("DaoTextReading"),l=i("DaoKeywordCards");return h(),u("div",null,[n[0]||(n[0]=e("",7)),a(o,{colophon:"季氏第十六 · 十四章",tone:"ink",sections:s,glossary:r,"default-mode":"slips","aria-label":"论语·季氏 原文"}),n[1]||(n[1]=t("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[m("【原典层】注音与字词 "),t("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),a(l,{items:[{term:"颛臾",pinyin:["zhuān","yú"],meaning:"鲁国的附属小国（风姓，相传为伏羲之后），当时为季氏采邑费地附近。"},{term:"陈力就列",pinyin:["chén","lì","jiù","liè"],meaning:"施展才力去就任职位。周任：古之良史。不能者止：不能胜任就该辞职。"},{term:"相",pinyin:["xiàng"],meaning:"辅佐、扶助（此指扶助盲者的人，引申为辅佐之臣）。"},{term:"虎兕出于柙，龟玉毁于椟中",pinyin:["hǔ","sì","chū","yú","xiá，","guī","yù","huǐ","yú","dú","zhōng"],meaning:"猛兽从笼中跑出，龟甲宝玉在匣里毁坏。兕：犀牛；柙：兽笼；椟：木匣。喻管事的人失职。"},{term:"舍曰欲之而必为之辞",pinyin:["shě","yuē","yù","zhī","ér","bì","wèi","zhī","cí"],meaning:"不肯直说自己想要，却一定要另找一套说辞。此为孔子批评冉有的话。"},{term:"陪臣执国命",pinyin:["péi","chén","zhí","guó","mìng"],meaning:"大夫的家臣把持国家政权。陪臣：大夫的家臣。"},{term:"三桓",pinyin:["sān","huán"],meaning:"鲁国孟孙、叔孙、季孙三家（皆桓公之后），世代把持鲁政。"},{term:"谅",pinyin:["liàng"],meaning:"诚信、信实（此处的「友谅」是褒义，与「君子贞而不谅」的「谅」义别）。"},{term:"便辟",pinyin:["pián","pì"],meaning:"逢迎谄媚。便：习熟；辟：同「僻」，偏邪。"},{term:"善柔",pinyin:["shàn","róu"],meaning:"工于柔媚、当面顺从。"},{term:"便佞",pinyin:["pián","nìng"],meaning:"巧言善辩而心术不正。"},{term:"佚游",pinyin:["yì","yóu"],meaning:"放纵游荡。佚：同「逸」，放荡。"},{term:"晏乐",pinyin:["yàn","lè"],meaning:"沉溺于宴饮之乐。"},{term:"愆",pinyin:["qiān"],meaning:"过失、差错。"},{term:"躁",pinyin:["zào"],meaning:"急躁（该说的时候还没到就抢先说）。"},{term:"隐",pinyin:["yǐn"],meaning:"隐匿、藏私（该说却不说）。"},{term:"瞽",pinyin:["gǔ"],meaning:"盲人（此处指像瞎子一样不看人脸色）。"},{term:"狎",pinyin:["xiá"],meaning:"轻慢、不尊重。"},{term:"千驷",pinyin:["qiān","sì"],meaning:"四千匹马。驷：同驾一车的四匹马。"}]}),n[2]||(n[2]=e("",25))])}}});export{b as __pageData,x as default};
